-- dwm workspaces in Rex's command palette.
--
-- Generated by `dwm setup`, which rewrites this file, so edits here are lost.
-- Bind an action to a key in init.lua, for example:
--
--   rex.bind("cmd+shift+w", "dwm_switch")

local DWM = "@DWM@"
local REX = "@REX@"
-- The PATH of the shell that ran `dwm setup`. Rex's own is minimal, and dwm
-- needs to find jj and git.
local PATH = "@PATH@"
local TERMINAL = "com.superlogical.terminal"
local SHELL = "com.superlogical.terminal.shell"

-- Programs Rex starts don't inherit a pane's environment, so tell dwm to use
-- Rex and where to find it, and that it isn't running in any pane.
local DWM_ENV = { PATH = PATH, DWM_REX = "1", DWM_REX_BIN = REX, REX_BLOCK = false, REX_SESSION = false }

local function list_workspaces(cwd)
  if cwd ~= nil then
    local r = rex.exec({ DWM, "status", "--json" }, { cwd = cwd, env = DWM_ENV, timeout = 30 })
    if r ~= nil and r.ok then
      return rex.json.decode(r.stdout)
    end
  end
  local r, err = rex.exec({ DWM, "status", "--all", "--json" }, { env = DWM_ENV, timeout = 60 })
  if r == nil then
    error("dwm: " .. tostring(err), 0)
  end
  if not r.ok then
    error("dwm: " .. r.stderr, 0)
  end
  return rex.json.decode(r.stdout)
end

-- Whether `dir` is inside a jj or git repository, so `dwm list` can run
-- there. Uses only tools in Rex's own minimal PATH.
local function in_repository(dir)
  if dir == nil then
    return false
  end
  local script = [[
d="$1"
while :; do
  if [ -e "$d/.jj" ] || [ -e "$d/.git" ]; then exit 0; fi
  [ "$d" = / ] && exit 1
  d=$(dirname "$d")
done]]
  local r = rex.exec({ "/bin/sh", "-c", script, "sh", dir }, { timeout = 5 })
  return r ~= nil and r.ok
end

local function focused_cwd(ctx)
  if ctx.block_id == nil then return nil end
  local ok, p = pcall(rex.block.call, TERMINAL, "process", { session_id = ctx.session_id, block_id = ctx.block_id })
  if not ok or type(p) ~= "table" then return nil end
  return (p.foreground and p.foreground.cwd) or (p.ancestors and p.ancestors[1] and p.ancestors[1].cwd)
end

-- Prefer the focused terminal's repo; outside one, ask explicitly rather
-- than guessing which registered repo to create in (or prune).
local function repository_cwd(ctx, title)
  local cwd = focused_cwd(ctx)
  if in_repository(cwd) then return cwd end
  if rex.ui == nil or rex.ui.pick == nil then
    error("dwm: focus a terminal inside the repository first", 0)
  end
  local items = {}
  for _, ws in ipairs(list_workspaces(nil).workspaces or {}) do
    if ws.is_main then
      table.insert(items, { id = ws.path, title = ws.repo or ws.name, subtitle = ws.path, icon = "folder" })
    end
  end
  if #items == 0 then
    error("dwm: no registered repositories; focus a terminal inside the repository first", 0)
  end
  return rex.ui.pick({ title = title, placeholder = "Filter repositories", items = items })
end

local function open_layer(ctx, cwd, argv)
  local _, err = rex.session.new_layer({
    session_id = ctx.session_id,
    bounds = { 0.05, 0.08, 0.9, 0.84 },
    focus = true,
    layout = rex.layout.block({ flavor = SHELL, options = { command = argv, cwd = cwd } }),
  })
  if err ~= nil then error("opening dwm pane: " .. tostring(err), 0) end
end

local function open_session(label, options)
  local created, err = rex.call("session.create", {
    label = label,
    initial_windows = {
      { layout = rex.layout.block({ flavor = SHELL, options = options }) },
    },
  })
  if created == nil then
    error("creating Rex session in " .. options.cwd .. ": " .. tostring(err), 0)
  end
  rex.client.queue("session.select", { session_id = created.session_id })
end

local function agent_detail(agents)
  if agents == nil then
    return nil
  end
  local parts = {}
  for _, key in ipairs({ "waiting", "working", "done", "idle" }) do
    if (agents[key] or 0) > 0 then
      table.insert(parts, agents[key] .. " " .. key)
    end
  end
  if #parts == 0 then
    return nil
  end
  return table.concat(parts, ", ")
end

rex.action({
  name = "dwm_switch",
  title = "dwm: Switch Workspace…",
  description = "Focus a dwm workspace's pane, or open a session for it",
  category = "dwm",
  keywords = "workspace worktree jj git",
  run = function(ctx)
    -- List the repository of the focused pane, or every repository.
    local cwd = focused_cwd(ctx)
    -- Rex servers before control API revision 17 have no prompts. Open dwm's
    -- own picker in a floating pane instead; it focuses or opens a session for
    -- the chosen workspace the same way, then exits and the pane closes.
    if rex.ui == nil or rex.ui.pick == nil then
      local argv = {
        "/usr/bin/env",
        "PATH=" .. PATH,
        "DWM_REX_BIN=" .. REX,
        "DWM_REX_THROWAWAY_PANE=1",
        DWM,
        "list",
      }
      if not in_repository(cwd) then
        table.insert(argv, "--all")
      end
      open_layer(ctx, cwd or os.getenv("HOME"), argv)
      return
    end

    local listing = list_workspaces(cwd)

    local items, by_path = {}, {}
    for _, ws in ipairs(listing.workspaces or {}) do
      local title = ws.name
      if ws.repo ~= nil and ws.repo ~= "" then
        title = ws.repo .. " / " .. ws.name
      end
      -- What an agent there says it is doing beats the commit description.
      local subtitle = ws.description
      local note = ws.agents and ws.agents.notes and ws.agents.notes[1]
      if note ~= nil then
        subtitle = note.status .. ": " .. note.text
      elseif subtitle == nil or subtitle == "" then
        subtitle = ws.path
      end
      table.insert(items, {
        id = ws.path,
        title = title,
        subtitle = subtitle,
        icon = ws.rex_pane and "terminal" or "branch",
        detail = agent_detail(ws.agents),
      })
      by_path[ws.path] = ws
    end

    local path = rex.ui.pick({ title = "Switch workspace", placeholder = "Filter workspaces", items = items })
    if path == nil then
      return
    end
    local ws = by_path[path]

    if ws.rex_pane ~= nil then
      local pane = ws.rex_pane
      rex.call("session.attach", { session_id = pane.session_id })
      rex.call("session.focus_block", { session_id = pane.session_id, block_id = pane.block_id })
      rex.client.queue("session.select", { session_id = pane.session_id, window_id = pane.window_id })
      return
    end

    open_session(ws.session_label or ws.name, { cwd = ws.path })
  end,
})

rex.action({
  name = "dwm_new",
  title = "dwm: New Workspace…",
  description = "Create a workspace and open a Rex session, optionally running a command",
  category = "dwm",
  keywords = "workspace worktree jj git agent",
  run = function(ctx)
    if rex.ui == nil or rex.ui.input == nil then
      error("dwm: this action needs Rex palette prompts; run `dwm new` in a terminal instead", 0)
    end
    local cwd = repository_cwd(ctx, "New workspace in which repository?")
    if cwd == nil then return end
    local name = rex.ui.input({ title = "Workspace name", placeholder = "Blank for a generated name", confirm = "Next" })
    if name == nil then return end
    -- Never let an input name become a dwm option or the command separator.
    if name:sub(1, 1) == "-" or name:find("%c") then
      error("dwm: workspace name cannot start with '-' or contain control characters", 0)
    end
    local command = rex.ui.input({ title = "Command to run in the new workspace", placeholder = "Blank for a shell", confirm = "Create workspace" })
    if command == nil then return end
    if command:find("%c") then error("dwm: enter a single command line", 0) end

    -- Let dwm provision the workspace, but let the palette open and select
    -- the session in its own client context, just like dwm_switch.
    local argv = { DWM, "new", "--here" }
    if name ~= "" then table.insert(argv, name) end
    local r, err = rex.exec(argv, { cwd = cwd, env = DWM_ENV })
    if r == nil then error("dwm: " .. tostring(err), 0) end
    if not r.ok then error("dwm new failed: " .. r.stderr, 0) end
    local path = r.stdout:gsub("\r?\n$", "")
    if path == "" then error("dwm new returned no workspace path", 0) end
    local options = { cwd = path }
    if command:find("%S") then options.initial_input = command .. "\r" end
    open_session(path:match("[^/]+$") or path, options)
  end,
})

-- Keep the CLI's live verdicts and deletion output visible without parsing
-- human-readable output or reimplementing its safety checks in Lua.
local prune_script = [[
if "$1" prune; then
  printf '\nDelete workspaces that are safe to prune? [y/N] '
  IFS= read -r answer || exit
  case "$answer" in
    y|Y|yes|YES) "$1" prune --yes ;;
    *) exit ;;
  esac
fi
printf '\nPress Return to close. '
IFS= read -r unused
]]

rex.action({
  name = "dwm_prune",
  title = "dwm: Prune Workspaces…",
  description = "Preview safe workspace cleanup, then confirm before deleting",
  category = "dwm",
  keywords = "workspace worktree jj git cleanup delete",
  run = function(ctx)
    local cwd = repository_cwd(ctx, "Prune workspaces in which repository?")
    if cwd == nil then return end
    open_layer(ctx, cwd, {
      "/usr/bin/env", "PATH=" .. PATH, "DWM_REX=1", "DWM_REX_BIN=" .. REX,
      "/bin/sh", "-c", prune_script, "dwm-prune", DWM,
    })
  end,
})
